class TestYamlShotGeneration:
    """Test orchestrator successfully generates video from YAML shot spec."""
    
    def test_yaml_shot_generation(self, tmp_path):
        """Orchestrator successfully generates video from YAML shot spec."""
        # Create a minimal script file
        script_data = {
            "title": "Test Movie",
            "scenes": [
                {
                    "visual": "A cityscape at sunset",
                    "action": ["Camera slowly pans across skyline"],
                    "shot_type": "wide shot",
                    "lighting": "golden hour lighting",
                    "duration_seconds": 8
                },
                {
                    "visual": "A lone figure walking down an alley",
                    "action": ["Figure walks toward camera"],
                    "shot_type": "medium shot",
                    "lighting": "noir lighting with hard shadows",
                    "duration_seconds": 4
                }
            ]
        }
        
        script_file = tmp_path / "script.json"
        with open(script_file, "w") as f:
            json.dump(script_data, f)
        
        # Create empty assets dir
        assets_dir = tmp_path / "assets"
        assets_dir.mkdir()
        
        # Run export
        veo_requests = export_to_veo(tmp_path, script_file, assets_dir)
        
        # Verify outputs exist
        export_dir = tmp_path / "veo_export"
        assert export_dir.exists()
        assert (export_dir / "manifest.yaml").exists()
        assert (export_dir / "shots").exists()
        assert (export_dir / "compiled").exists()
        
        # Verify compiled JSON files
        compiled_files = list((export_dir / "compiled").glob("*.json"))
        assert len(compiled_files) == 2, f"Expected 2 compiled files, got {len(compiled_files)}"
        
        # Verify compiled requests structure
        assert len(veo_requests) == 2
        for req in veo_requests:
            assert "prompt" in req
            assert "config" in req
            assert "duration_seconds" in req["config"]
            assert "aspect_ratio" in req["config"]
            assert "model" in req
    
    def test_shot_duration_clamping(self, tmp_path):
        """Invalid durations are clamped to nearest valid value."""
        script_data = {
            "title": "Duration Test",
            "scenes": [
                {
                    "visual": "Test scene",
                    "duration_seconds": 5  # Invalid, should clamp to 4
                },
                {
                    "visual": "Test scene 2",
                    "duration_seconds": 10  # Invalid, should clamp to 8
                },
                {
                    "visual": "Test scene 3",
                    "duration_seconds": 20  # Invalid, should clamp to 16
                }
            ]
        }
        
        script_file = tmp_path / "script.json"
        with open(script_file, "w") as f:
            json.dump(script_data, f)
        
        assets_dir = tmp_path / "assets"
        assets_dir.mkdir()
        
        veo_requests = export_to_veo(tmp_path, script_file, assets_dir)
        
        durations = [r["config"]["duration_seconds"] for r in veo_requests]
        assert durations[0] == 4, f"5s should clamp to 4, got {durations[0]}"
        assert durations[1] == 8, f"10s should clamp to 8, got {durations[1]}"
        assert durations[2] == 16, f"20s should clamp to 16, got {durations[2]}"
    
    def test_asset_linking(self, tmp_path):
        """Reference images are linked to shot specs."""
        script_data = {
            "title": "Asset Test",
            "scenes": [{"visual": "Test"}]
        }
        
        script_file = tmp_path / "script.json"
        with open(script_file, "w") as f:
            json.dump(script_data, f)
        
        # Create a dummy asset
        assets_dir = tmp_path / "assets"
        assets_dir.mkdir()
        (assets_dir / "scene_001.png").write_bytes(b"fake png")
        
        export_to_veo(tmp_path, script_file, assets_dir)
        
        # Check asset was copied
        export_assets = tmp_path / "veo_export" / "assets"
        assert any(export_assets.glob("*.png")), "Asset should be copied to export dir"


class TestVeoAdapter:
    """Direct tests for VeoAdapter class."""
    
    def test_adapter_creates_structure(self, tmp_path):
        """VeoAdapter creates expected directory structure."""
        adapter = VeoAdapter(tmp_path)
        
        script_data = {"title": "Test", "scenes": [{"visual": "Scene 1"}]}
        adapter.prepare_export(script_data)
        
        assert adapter.export_dir.exists()
        assert adapter.assets_dir.exists()
        assert adapter.shots_dir.exists()
        assert adapter.manifest_file.exists()
    
    def test_adapter_compiles_shots(self, tmp_path):
        """VeoAdapter compiles shots to valid Veo JSON."""
        adapter = VeoAdapter(tmp_path)
        
        script_data = {
            "title": "Test",
            "scenes": [
                {"visual": "Scene 1", "duration_seconds": 8},
                {"visual": "Scene 2", "duration_seconds": 4}
            ]
        }
        adapter.prepare_export(script_data)
        
        compiled = adapter.compile_all_shots()
        
        assert len(compiled) == 2
        assert adapter.compiled_dir.exists()
        assert len(list(adapter.compiled_dir.glob("*.json"))) == 2


